arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/bash
case "$1" in
  *Username*) echo "x-access-token" ;;
  *Password*) printf '%s' "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh && cd /tmp/ross-conv && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/ross 2>&1 | tail -5

cd /tmp && python3 - <<'EOF'
import subprocess, re
REPO="/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
def git(*a):
    return subprocess.run(["git","-C",REPO]+list(a),capture_output=True,text=True).stdout
files=[f for f in git("ls-tree","-r","--name-only","origin/main").split() if re.match(r"S\d+/E\d+\.md$",f)]
bad=[]
for f in files:
    txt=git("show","origin/main:%s"%f)
    m=re.match(r"^---\n(.*?)\n---\n\n(.*?)\n\n+", txt, re.S)
    if not m: bad.append((f,"no header")); continue
    fm=m.group(1); para=m.group(2).strip()
    summ=re.search(r'^summary: "(.*)"$', fm, re.M)
    title=re.search(r'^title: "(.*)"$', fm, re.M)
    if not summ: bad.append((f,"no summary")); continue
    if summ.group(1).strip()!=para: bad.append((f,"summary != paragraph"))
    if not title: bad.append((f,"no title"))
    if not re.search(r"^season: \d+$", fm, re.M): bad.append((f,"no season"))
    if not re.search(r"^episode: \d+$", fm, re.M): bad.append((f,"no episode"))
    if not re.search(r"^status: (ongoing|complete)$", fm, re.M): bad.append((f,"bad status"))
print("files:",len(files),"issues:",len(bad))
for b in bad[:20]: print(" ",b)
EOF
